    pub fn to_meta(&self) -> TypeMeta { ... }
    pub fn to_shallow(&self) -> TypeShallow { ... }
}
impl Design {
    pub fn to_meta(&self) -> DesignMeta { ... }
    pub fn to_shallow(&self) -> DesignShallow { ... }
}
impl Kit {
    pub fn to_meta(&self) -> KitMeta { ... }
    pub fn to_shallow(&self) -> KitShallow { ... }
